  gulp.task('font', () => {
    return gulp
      .src(path.join(
        dir.source,
        dir.asset,
        dir.font,
        gulpConfig.fileExpression.font
      ))
      .pipe(plugins.changed(dest))
      // .pipe(plugins.debug())

      // Fix for Windows 10 and gulp acting crazy
      .pipe(plugins.rename(file => {
        fixWindows10GulpPathIssue({file, dest, plugins, config})
      }))
      // .pipe(plugins.debug())
      .pipe(gulp.dest(dest));
  });
};

